   output: [8, 6, -1, -1, -1, -1, -1]

   input: [5, 4, 6, 4, 3, 6, 1, 1]
   output: [5, 4, 4, 4, 3, 3, 1, 1]
*/
void partialMinimums(std::vector<float> &x) {
    // Use a temporary vector to store the minimum values
    std::vector<float> min_values(x.size());
    min_values[0] = x[0];
    for (size_t i = 1; i < x.size(); ++i) {
        min_values[i] = std::min(x[i], min_values[i - 1]);
    }
    x = std::move(min_values); // Move the temporary vector back to x
}

