   input: [-1.8, 24.0, 1.2, 0.0, -5.1, -0.2, 4.5]
   output: [0, 24.0, 1.2, 0, 0, 0, 4.5]
*/
void relu(std::vector<double> &x) {
    // Use a custom lambda function instead of a lambda expression
    std::transform(x.begin(), x.end(), x.begin(), [](double v) {
        return (v > 0.0)? v : 0.0;
    });
}

