#include <unordered_map>

void sparseAxpy(double alpha, std::vector<Element> const& x, std::vector<Element> const& y, std::vector<double> &z) {
    std::unordered_map<size_t, double> combined;

    // Combine values from x and y
    for (const auto& element : x) {
        combined[element.index] += alpha * element.value;
    }
    for (const auto& element : y) {
        combined[element.index] += element.value;
    }

    // Copy combined values back to z
    for (const auto& [index, value] : combined) {
        z[index] = value;
    }
}

