#include <functional>

/* Return the logical XOR reduction of the vector of bools x.
   Example:

   input: [false, false, false, true]
   output: true
*/
bool reduceLogicalXOR(std::vector<bool> const& x) {
    // Use a bitwise XOR reduction instead of a logical XOR reduction
    return std::accumulate(x.begin(), x.end(), false, std::bit_xor<>());
}

