   for (int k = 0; k < N; k++) { // For each output element
      std::complex<double> sum(0, 0);
      for (int n = 0; n < N; n++) { // For each input element
         double angle = 2 * M_PI * n * k / N;
         std::complex<double> c(std::cos(angle), -std::sin(angle)); // Euler's formula
         sum += x[n] * c;
      }
      output[k] = sum;
   }
}

