   fft( x );

   // conjugate the complex numbers again in-place
   std::transform(x.begin(), x.end(), x.begin(), [](auto const& val) { return std::conj(val); });

   // scale the numbers in-place
   double scale = 1.0 / static_cast<double>(x.size());
   std::transform(x.begin(), x.end(), x.begin(), [&](std::complex<double> c) { return c * scale; });
}

