    // Handle the first element separately to avoid accessing input[-1]
    output[0] = (input[0] + input[1]) * scale;

    // Handle the middle elements
    for (size_t i = 1; i < input.size() - 1; i++) {
        output[i] = (input[i - 1] + input[i] + input[i + 1]) * scale;
    }

    // Handle the last element separately to avoid accessing input[input.size()]
    output[input.size() - 1] = (input[input.size() - 2] + input[input.size() - 1]) * scale;
}

