    // Create a temporary buffer to store the counts for each cell
    std::vector<int> counts(N * N, 0);

    // First pass: count the neighbors for each cell
    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j < N; ++j) {
            if (input[i*N + j] == 1) {
                if (i > 0) counts[(i-1)*N + j]++;
                if (i < N-1) counts[(i+1)*N + j]++;
                if (j > 0) counts[i*N + j-1]++;
                if (j < N-1) counts[i*N + j+1]++;
            }
        }
    }

    // Second pass: set output values based on counts
    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j < N; ++j) {
            output[i*N + j] = (counts[i*N + j] == 1)? 1 : 0;
        }
    }
}

