*/
void jacobi2D(std::vector<double> const& input, std::vector<double> &output, size_t N) {
    // Create a local copy of input to avoid accessing input multiple times
    std::vector<double> local_input = input;
    for (size_t i = 0; i < N; i++) {
        for (size_t j = 0; j < N; j++) {
            // Calculate the sum using the local copy
            double sum = 0;
            if (i > 0) {
                sum += local_input[(i - 1) * N + j];
            } else {
                // Handle the case when i == 0
                sum += input[j]; // Use the original input value
            }
            if (i < N - 1) {
                sum += local_input[(i + 1) * N + j];
            } else {
                // Handle the case when i == N - 1
                sum += input[i * N + j]; // Use the original input value
            }
            if (j > 0) {
                sum += local_input[i * N + (j - 1)];
            } else {
                // Handle the case when j == 0
                sum += input[i * N + j]; // Use the original input value
            }
            if (j < N - 1) {
                sum += local_input[i * N + (j + 1)];
            } else {
                // Handle the case when j == N - 1
                sum += input[i * N + j]; // Use the original input value
            }
            sum += local_input[i * N + j];
            output[i * N + j] = sum / 5.0;
        }
    }
}

