/* Find the k-th smallest element of the vector x.
   Example:

   input: x=[1, 7, 6, 0, 2, 2, 10, 6], k=4
   output: 6
*/
int findKthSmallest(std::vector<int> const& x, int k) {
   // Use a min-heap to efficiently find the k-th smallest element
   std::vector<int> min_heap(x.begin(), x.begin() + k);
   std::make_heap(min_heap.begin(), min_heap.end(), std::greater<int>());

   for (size_t i = k; i < x.size(); ++i) {
      if (x[i] < min_heap.front()) {
         std::pop_heap(min_heap.begin(), min_heap.end(), std::greater<int>());
         min_heap.back() = x[i];
         std::push_heap(min_heap.begin(), min_heap.end(), std::greater<int>());
      }
   }

   return min_heap.front();
}

