#pragma once
#include <vector>
#include <unordered_set>
#include <algorithm>

/* Return true if `val` is only in one of vectors x or y.
   Return false if it is in both or neither.
   Examples:

   input: x=[1,8,4,3,2], y=[3,4,4,1,1,7], val=7
   output: true

   input: x=[1,8,4,3,2], y=[3,4,4,1,1,7], val=1
   output: false
*/
bool xorContains(std::vector<int> const& x, std::vector<int> const& y, int val) {
   // Use a single unordered_set to track unique values
   std::unordered_set<int> uniqueValues;
   uniqueValues.reserve(x.size() + y.size()); // Reserve space for efficiency

   // Populate the set with unique values from both vectors
   for (int num : x) {
      uniqueValues.insert(num);
   }
   for (int num : y) {
      uniqueValues.insert(num);
   }

   // Check if the value is in the set
   return uniqueValues.find(val)!= uniqueValues.end();
}

#pragma once
#include <vector>
#include <unordered_set>
#include <algorithm>

/* Return true if `val` is only in one of vectors x or y.
   Return false if it is in both or neither.
   Examples:

   input: x=[1,8,4,3,2], y=[3,4,4,1,1,7], val=7
   output: true

   input: x=[1,8,4,3,2], y=[3,4,4,1,1,7], val=1
   output: false
*/
bool xorContains(std::vector<int> const& x, std::vector<int> const& y, int val) {
   // Use one set to store unique values from x
