/* Return true if the vector x contains the value `target`. Return false otherwise.
   Examples:

   input: x=[1, 8, 2, 6, 4, 6], target=3
   output: false

   input: x=[1, 8, 2, 6, 4, 6], target=8
   output: true
*/
bool contains(std::vector<int> const& x, int target) {
    // Use an unordered_set to store unique values from the vector
    std::unordered_set<int> unique_values(x.begin(), x.end());
    return unique_values.find(target)!= unique_values.end();
}

